'use strict';
// UI exploration only. State lives in memory; no real files, model or host API is read.
const $ = (s) => document.querySelector(s);
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',folder:'M3 7h7l2 2h9v12H3ZM3 7V4h7l2 3',chart:'M4 3v17h17M7 14l4-5 4 3 5-7',clinical:'M9 3h6v6h6v6h-6v6H9v-6H3V9h6Z',food:'M7 3v8m-3-8v5a3 3 0 0 0 6 0V3M7 11v10M19 3c-4 3-4 9 0 10V3Zm0 10v8',heart:'M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-5 5 8 15 8 15s13-10 8-15Z',calendar:'M4 5h16v16H4ZM8 3v4m8-4v4M4 10h16m-12 4h2m4 0h2m-8 3h2',bookmark:'M6 3h12v19l-6-4-6 4Z'};
const icon = (key) => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[key]}"/></svg>`;
const pages = [['dashboard','看板','home'],['records','病情整理','folder'],['timeline','病情一图秀','chart'],['clinical','临床','clinical'],['nutrition','营养支持','food'],['mind','心理支持','heart'],['care','全程管理','calendar'],['review','收藏与回顾','bookmark']];
const subpages = {records:['资料库','整理草稿 / 核对','病情档案','指标检测','病情汇总'],clinical:['治疗历程','病理 / 分子档案','试验检索','资料对照','我的关注','数据来源'],nutrition:['当下困扰','进食与体重','建议与回顾'],mind:['当下感受','我的记录','支持资源'],care:['近期安排','不适记录','康复与长期生活','就诊准备'],review:['问题清单','已保留结果','报告与任务']};
const subtitles = {dashboard:'把眼前的事情理清楚，让每次记录都能继续帮到你。',records:'原始材料有出处，整理结果可核对，一次记录多处复用。',timeline:'把治疗、检查和变化放回同一段时间里。',clinical:'看懂自己的治疗资料，也为下一次讨论做好准备。',nutrition:'从今天吃得怎么样开始，少量记录也有意义。',mind:'这里可以放下感受，不需要整理好情绪再开始。',care:'治疗之外，也照顾日常的节奏。',review:'重要的问题和结果，在需要的时候找得到。'};
const state = {page:'dashboard',sub:{},stage:'治疗期间',query:'',range:'全部',parsing:false,parseError:false,loaded:false,
  docs:[{id:'d1',name:'病理报告 · 示例',date:'2026-08-12',type:'病理',status:'已核对'},{id:'d2',name:'血常规报告 · 示例',date:'2026-10-12',type:'检验',status:'已核对'},{id:'d3',name:'治疗记录 · 示例',date:'2026-10-12',type:'治疗',status:'待核对'}],
  candidates:[{id:'c1',name:'实际治疗日期',value:'2026-10-12',source:'治疗记录 · 第 1 页',status:'candidate'},{id:'c2',name:'治疗记录名称',value:'第 2 次治疗（示例）',source:'治疗记录 · 第 1 页',status:'candidate'},{id:'c3',name:'下一次就诊时间',value:'原文日期不清晰',source:'治疗记录 · 第 1 页',status:'needs_review'}],
  questions:[{id:'q1',text:'下次复诊前，需要带齐哪些报告和用药记录？',source:'本人保留 · 模拟问题',selected:true},{id:'q2',text:'最近疲劳和进食变化，需要怎样向治疗团队描述？',source:'本人保留 · 模拟问题',selected:true}],
  events:[{id:'e1',date:'08.12',title:'病理报告归档',type:'检查资料',source:'病理报告 · 示例'},{id:'e2',date:'09.21',title:'第 1 次治疗记录',type:'实际事件',source:'治疗记录 · 示例'},{id:'e3',date:'10.12',title:'血常规报告归档',type:'检查资料',source:'血常规报告 · 示例'}],
  tasks:[{id:'t1',date:'10.20',title:'整理本次复诊资料',note:'本人安排 · 就诊前准备',done:false},{id:'t2',date:'10.22',title:'复诊时间待向医院确认',note:'模拟安排 · 时间尚未确认',done:false}],
  nutrition:[],moods:[],symptoms:[],saved:[],favorite:false,metricOpen:{},privacy:'本人',toastTimer:null};
const btn = (text, action, cls='', extra='') => `<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const go = (text,page,sub='',cls='') => btn(text,'go',cls,`data-page="${page}" data-sub="${esc(sub)}"`);
const pill = (text,cls='') => `<span class="pill ${cls}">${text}</span>`;
function toast(text){clearTimeout(state.toastTimer);$('#toast').textContent=text;$('#toast').classList.add('visible');state.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function openModal(title,body,foot='',eyebrow='小粉宝 · 交互演示'){ $('#dialog-title').textContent=title;$('#dialog-eyebrow').textContent=eyebrow;$('#dialog-body').innerHTML=body;$('#dialog-foot').innerHTML=foot;if(!$('#dialog').open)$('#dialog').showModal();document.body.style.overflow='hidden';}
function closeModal(){$('#dialog').close();}
$('#dialog').addEventListener('close',()=>{document.body.style.overflow='';});
function navigate(page,sub){state.page=page;if(sub)state.sub[page]=sub;state.query='';render();$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function head(title,action=''){return `<div class="page-head"><div><span class="eyebrow">PINKYPAL / YOUR CARE COMPANION</span><h1>${title}</h1><p>${subtitles[state.page]}</p></div><div class="actions">${action}</div></div>`;}
function subnav(){const items=subpages[state.page];if(!items)return '';const selected=state.sub[state.page]||items[0];return `<nav class="subnav" aria-label="${pages.find(p=>p[0]===state.page)[1]}二级页面" role="tablist">${items.map(s=>`<button role="tab" aria-selected="${selected===s}" data-action="sub" data-sub="${s}">${s}</button>`).join('')}</nav>`;}
function section(title,desc='',action=''){return `<div class="section-title"><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`;}
function timelineList(limit){const list=state.range==='近期'?state.events.filter(e=>e.date.startsWith('10')):state.events;return `<div class="timeline">${list.slice().reverse().slice(0,limit||99).map(e=>`<div class="timeline-item"><small>2026.${e.date} · ${esc(e.type)}</small><b>${esc(e.title)}</b><p>来源：${esc(e.source)}</p>${btn('查看来源 ↗','source','text-button',`data-source="${esc(e.source)}"`)}</div>`).join('')}</div>`;}
function tasksList(){return state.tasks.map(t=>`<div class="row ${t.done?'completed':''}"><div class="row-main">${btn(t.done?'✓':'','task-toggle',`check-button ${t.done?'done':''}`,`data-id="${t.id}" aria-label="${t.done?'重开':'完成'}：${esc(t.title)}"`)}<div><small>${t.date.includes('-')?t.date:'2026.'+t.date}</small><b>${esc(t.title)}</b><p>${esc(t.note)}</p></div></div>${btn('详情','task-detail','text-button',`data-id="${t.id}"`)}</div>`).join('');}
function dashboard(){return `${head('今天，先照顾眼前的一件事。',`<label class="muted"><span class="form-label">当前关注阶段</span><select class="stage-select" id="stage-select">${['刚确诊','治疗期间','术后恢复','长期治疗 / 随访','进一步评估期间'].map(v=>`<option ${state.stage===v?'selected':''}>${v}</option>`).join('')}</select></label>`)}
  <section class="hero"><div><div class="eyebrow">慢慢来，每一步都算数</div><h1>资料帮你理，<br>重要的事一起记。</h1><p>不必一次填完所有信息。可以先交一份材料，记下一点变化，或者只留下一个想问的问题。</p><div class="actions">${go('整理我的资料 →','records','资料库','primary')}${btn('准备就诊问题','questions')}</div></div><div class="hero-mascot"><img src="../../assets/brand/pinkypal-logo-original.jpg" alt="小粉宝陪伴你"></div></section>
  <div class="grid three"><button class="task-entry" data-action="welcome"><span class="entry-icon">♡</span><b>刚确诊，有些不知所措</b><span>从理解眼前的情况开始</span><span class="arrow">↗</span></button><button class="task-entry" data-action="go" data-page="records" data-sub="整理草稿 / 核对"><span class="entry-icon">▤</span><b>资料很多，帮我理清楚</b><span>先看草稿，有疑点再慢慢核对</span><span class="arrow">↗</span></button><button class="task-entry" data-action="record"><span class="entry-icon">＋</span><b>记下今天的一点变化</b><span>身体、进食和感受，任选一项</span><span class="arrow">↗</span></button></div>
  <div class="dashboard-grid"><div>${section('最近的病程','同一份资料，留在同一条病程里。',go('查看一图秀 ↗','timeline','','text-button'))}<section class="card">${timelineList(3)}<div class="stat-band"><span><b>${state.docs.length}</b>份模拟材料</span><span><b>${state.candidates.filter(c=>c.status!=='accepted').length}</b>项尚未核对</span><span><b>${state.questions.length}</b>个就诊问题</span></div></section>${section('照护，也有日常的一面')}<div class="grid two"><section class="card"><div class="card-head"><h3>今天吃得怎么样？</h3>${pill('营养','green')}</div><p>只记录食欲或进食困难也可以，不需要计算每一口。</p>${go('从一条记录开始 →','nutrition','进食与体重','text-button')}</section><section class="card"><div class="card-head"><h3>感受值得被好好放下</h3>${pill('心理','pink')}</div><p>可以自己留着，也可以选择准备向他人表达。</p>${go('留一点空间给自己 →','mind','当下感受','text-button')}</section></div></div><div>${section('接下来的安排',`${state.tasks.filter(t=>!t.done).length} 项待办`,btn('＋ 添加','add-task','text-button'))}<section class="card">${tasksList()}${go('全部安排 →','care','近期安排','text-button')}</section>${section('就诊前，想问的事', '',btn('编辑','questions','text-button'))}<section class="card accent">${state.questions.slice(0,2).map(q=>`<div class="row"><div><b>${esc(q.text)}</b><p>${esc(q.source)}</p></div></div>`).join('')}<div class="small-note">问题会保留到“收藏与回顾”，下次不用重新整理。</div></section></div></div>`;}
function docsTable(){const docs=state.docs.filter(d=>d.name.includes(state.query)||d.type.includes(state.query));return `<div class="table-wrap"><table><thead><tr><th>材料名称</th><th>发生日期</th><th>类型</th><th>整理状态</th><th>操作</th></tr></thead><tbody>${docs.map(d=>`<tr><td><b>${esc(d.name)}</b><br><small>模拟资料 · 无真实文件</small></td><td>${d.date}</td><td>${d.type}</td><td>${pill(d.status,d.status==='已核对'?'green':'yellow')}</td><td>${btn('原文','source','source-link',`data-source="${esc(d.name)}"`)} ${d.status==='待核对'?go('看草稿','records','整理草稿 / 核对','source-link'):''}</td></tr>`).join('')}</tbody></table></div>${!docs.length?'<div class="empty"><h3>没有找到这份材料</h3><p>试试“病理”“检验”或清空搜索。</p></div>':''}`;}
function candidateRows(){return state.candidates.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.value)}</td><td>${btn('第 1 页 ↗','source','source-link',`data-source="治疗记录 · 示例"`)}</td><td>${pill(c.status==='accepted'?'已核对':c.status==='needs_review'?'需要确认':'未核对',c.status==='accepted'?'green':'yellow')}</td><td>${btn('查看 / 更正','candidate','text-button',`data-id="${c.id}"`)}</td></tr>`).join('');}
function records(){const sub=state.sub.records||subpages.records[0];let body='';if(sub==='资料库')body=`<div class="toolbar"><input id="search" aria-label="搜索模拟材料" placeholder="搜索材料名称或类型" value="${esc(state.query)}"><div class="actions">${pill('全部模拟数据','pink')}${btn('载入模拟报告','load-report','primary')}${btn('演示解析失败','parse-fail')}</div></div>${state.parsing?'<div class="card loading-line" role="status">正在整理模拟材料，切换页面也不会丢失进度…</div>':''}${state.parseError?`<div class="notice demo-error">模拟解析失败。材料仍保留，可重试或手工核对。${btn('重试','retry','text-button')}</div>`:''}<div class="card" id="docs-table">${docsTable()}</div><div class="help-box">💡 这版先演示资料的组织方式。导入、OCR、真实文件和云端处理均未接入。</div>`;
else if(sub==='整理草稿 / 核对')body=`<div class="flow-steps"><span>原始材料</span>→<span>整理草稿</span>→<span>按需核对</span>→<span>病程 / 就诊准备</span></div><div class="notice">整理草稿 · 以下仍有未核对内容。可以先看资料轮廓，暂时不处理疑点。</div><div class="card"><div class="card-head"><div><h2>这一份治疗记录，先帮你理到这里</h2><p>模拟摘录 · 不含治疗建议</p></div>${btn('查看原文','source','soft','data-source="治疗记录 · 示例"')}</div><p>材料记载了一次治疗及后续就诊安排。实际日期和记录名称可回源核对；下一次就诊日期不清晰，暂未写入安排。</p><div class="table-wrap"><table><thead><tr><th>项目</th><th>材料中的内容</th><th>来源</th><th>状态</th><th>操作</th></tr></thead><tbody>${candidateRows()}</tbody></table></div><div class="form-actions">${go('现在先不核对','timeline')}${btn('保留核实问题','add-review-question','primary')}</div></div>`;
else if(sub==='病情档案')body=`<div class="notice pink">模拟档案 · 不同标本、病灶与时间的结果分别保留，不能用一份最新报告覆盖全部历史。</div><div class="grid two"><section class="card"><div class="card-head"><h2>病理资料</h2>${pill('模拟转录','green')}</div><dl class="two-col-info"><dt>取样日期</dt><dd>2026-08-12</dd><dt>报告名称</dt><dd>病理报告 · 示例</dd><dt>取样部位</dt><dd>左侧乳腺（模拟）</dd><dt>组织学 / 分期</dt><dd>此原型未填入</dd><dt>ER / PR / HER2</dt><dd>保留报告原文的位置，待字段设计核验</dd></dl>${btn('查看原报告 ↗','source','text-button','data-source="病理报告 · 示例"')}</section><section class="card"><h2>当前资料还缺什么？</h2><p>缺项表示资料尚未录入，不代表需要补做检查。</p><div class="row"><div><b>手术 / 出院材料</b><p>暂未载入模拟材料</p></div>${pill('未知')}</div><div class="row"><div><b>既往治疗安排</b><p>从已有文书或本人记录补充</p></div>${pill('待整理')}</div>${go('继续整理材料 →','records','资料库','text-button')}</section></div>`;
else if(sub==='指标检测')body=metrics();else body=summary();return head('病情整理',btn('准备问题清单','questions','primary'))+subnav()+body;}
function chart(small=false){const points=[{x:50,y:87,date:'08.20',v:'5.1'},{x:150,y:111,date:'09.10',v:'4.6'},{x:250,y:94,date:'10.01',v:'4.9'},{x:350,y:130,date:'10.12',v:'4.2'}];return `<svg class="chart" viewBox="0 0 400 190" role="img" aria-label="白细胞模拟记录折线，8月20日5.1、9月10日4.6、10月1日4.9、10月12日4.2，单位10的9次方每升；仅用于交互演示"><g>${[50,100,150].map((y,i)=>`<line class="grid-line" x1="38" y1="${y}" x2="385" y2="${y}"/><text x="8" y="${y+4}">${6-i*2}</text>`).join('')}<path class="chart-line" d="M50 87 L150 111 L250 94 L350 130"/>${points.map(p=>`<circle tabindex="0" role="button" aria-label="查看${p.date}的模拟值${p.v}" class="data-point" cx="${p.x}" cy="${p.y}" r="5" data-action="point" data-date="${p.date}" data-value="${p.v}"/><text x="${p.x}" y="180" text-anchor="middle">${p.date}</text>`).join('')}</g></svg>`;}
function metrics(){return `<div class="notice neutral">以下为模拟数值。趋势只呈现记录，不代表疗效、复发或诊断判断；不同单位和方法需分开核对。</div><div class="grid three">${[['wbc','白细胞','4.2','10⁹/L'],['weight','体重','58.0','kg'],['other','其他指标','—','未录入']].map(([id,name,val,unit])=>`<div><button class="metric-toggle" aria-expanded="${!!state.metricOpen[id]}" data-action="metric" data-id="${id}"><div class="kicker"><span>${name}</span><span>${state.metricOpen[id]?'收起 ↑':'查看记录 ↗'}</span></div><div class="metric-value">${val}<small>${unit}</small></div><p>模拟记录 · ${id==='other'?'缺失不按零计算':'2026-10-12'}</p></button>${state.metricOpen[id]?`<div class="card metric-chart">${id==='wbc'?chart(true):`<p>${id==='weight'?'本次 58.0 kg（模拟）；只有一条记录，暂不连线。':'暂无记录。可从资料库整理已有报告，不提示补做检测。'}</p>`}</div>`:''}</div>`).join('')}</div><section class="card" style="margin-top:22px"><div class="card-head"><h2>检测记录</h2>${go('病程里看变化 ↗','timeline','','text-button')}</div><div class="table-wrap"><table><thead><tr><th>采样日期</th><th>指标</th><th>数值 / 单位</th><th>来源 / 状态</th></tr></thead><tbody><tr><td>2026-10-12</td><td>白细胞</td><td>4.2 × 10⁹/L</td><td>${btn('血常规报告 · 示例 ↗','source','source-link','data-source="血常规报告 · 示例"')} · 已核对</td></tr></tbody></table></div></section>`;}
function summary(){return `<div class="grid two"><section class="card"><div class="card-head"><h2>就诊摘要预览</h2>${pill('模拟资料','pink')}</div><p>范围：2026-08 至 2026-10 · 本次原型只预览资料组织与分享选择。</p><div class="row"><div><b>病情与治疗材料</b><p>${state.docs.length}份示例材料，保留各自日期与核对状态。</p></div></div><div class="row"><div><b>最近变化</b><p>已保存${state.nutrition.length}条进食记录、${state.symptoms.length}条不适记录。</p></div></div><div class="row"><div><b>准备讨论的问题</b><p>${state.questions.length}个，可编辑和选择。</p></div></div><div class="notice pink">心理私密内容默认不进入这份模拟摘要。</div>${btn('编辑并导出问题清单','questions','primary')}</section><section class="card"><h2>分享之前，再看一眼</h2><p>未核对内容与来源状态应在所有格式保留。原型下载仅包含主动选择的问题，不下载病历或心理记录。</p><details><summary>此处未来会包含什么？</summary><p>资料范围、来源版本、已核对与草稿区分、可选分享、真实文件导出及历史版本。</p></details><div class="small-note">PDF、JPEG、HTML、DOCX业务导出未实现；当前可下载模拟问题的Markdown文件。</div></section></div>`;}
function timelinePage(){return head('病情一图秀',btn('准备讨论的问题','questions','primary'))+`<div class="toolbar"><div class="actions">${pill('2026.08 — 2026.10','pink')}${pill('已核对模拟记录','green')}</div><label><span class="form-label">时间范围</span><select id="range-select"><option ${state.range==='全部'?'selected':''}>全部</option><option ${state.range==='近期'?'selected':''}>近期</option></select></label></div><div class="grid two"><section class="card"><div class="card-head"><div><h2>白细胞记录</h2><p>单位 10⁹/L · 模拟数值 · 点选可追溯</p></div>${go('指标检测 ↗','records','指标检测','text-button')}</div>${state.range==='全部'?chart():`<div class="empty"><h3>近期 2 条模拟记录</h3><p>10.01：4.9 · 10.12：4.2（10⁹/L）</p>${btn('查看最近记录','point','soft','data-date="10.12" data-value="4.2"')}</div>`}<div class="treatment-strip"><span>09.21 第1次治疗</span><span>10.12 待核对治疗记录</span></div><p class="small-note">治疗日期用于对照，不从相邻变化推断因果或疗效。待核对事件与正式记录分开。</p></section><section class="card"><div class="card-head"><h2>这一段病程</h2>${pill('同源引用')}</div>${timelineList()}<div class="small-note">${state.candidates.filter(c=>c.status!=='accepted').length}项待核对内容仍留在整理草稿中。</div></section></div>${section('想多看一点时，再展开','每张指标卡可独立展开；只读已核对的模拟记录。')}${metrics()}`;}
function clinical(){const sub=state.sub.clinical||subpages.clinical[0];let body='';if(sub==='治疗历程')body=`<div class="notice pink">计划与实际分别保存。完成待办，不会自动生成实际治疗。</div><div class="card"><div class="card-head"><h2>已记录的治疗</h2>${go('关联原始材料','records','资料库','text-button')}</div>${timelineList()}<div class="row"><div><b>尚未核对的治疗材料</b><p>仅为草稿，不作为已经完成的给药记录。</p></div>${go('查看草稿','records','整理草稿 / 核对','soft')}</div></div>`;
else if(sub==='病理 / 分子档案')body=`<div class="card"><h2>按标本和时间，保留每一份结果</h2><p>病理、分子与遗传材料各有来源；没有检测、未录入和未检出分别表达。</p><div class="row"><div><b>2026-08-12 · 病理报告示例</b><p>左侧乳腺 · 模拟文书 · 具体字段尚未填入</p></div>${go('查看病情档案','records','病情档案','soft')}</div><div class="empty"><h3>分子 / 遗传材料尚未载入</h3><p>此状态不表示结果阴性，也不提示必须检测。</p></div></div>`;
else if(sub==='试验检索')body=`<div class="notice">以下是虚构交互条目，不是临床试验信息。没有接入登记平台或真实研究数据。</div><div class="card"><div class="toolbar"><h2>研究线索的查看方式</h2>${btn(state.favorite?'已关注 ✓':'关注示例条目','favorite',state.favorite?'soft':'primary')}</div><h3>乳腺癌相关研究 · 示例条目 A</h3><p>原型只演示“详情 → 资料对照 → 核实问题 → 关注”的任务路径。研究名称、中心、状态和条件均未填入真实信息。</p><div class="actions" style="margin-top:20px">${btn('查看示例详情','trial-detail')}${go('用我的资料对照','clinical','资料对照','soft')}</div></div>`;
else if(sub==='资料对照')body=`<div class="card"><h2>先列出已知和未知，交给研究中心核实</h2><div class="table-wrap"><table><thead><tr><th>资料项</th><th>目前记录</th><th>需要做的沟通</th></tr></thead><tbody><tr><td>病理资料</td><td>有模拟报告</td><td>核实标本与报告信息是否完整</td></tr><tr><td>既往治疗</td><td>仍有待核对内容</td><td>整理已实际接受的方案与时间</td></tr><tr><td>研究条件</td><td>尚未接入真实数据</td><td>以登记原文及中心答复核实</td></tr></tbody></table></div><p>资料对照不输出适合率、匹配排名或入组结论。</p>${btn('加入核实问题','add-trial-question','primary')}</div>`;
else if(sub==='我的关注')body=state.favorite?`<div class="card"><h2>示例条目 A</h2><p>虚构条目 · 仅验证关注后的回顾路径。</p><div class="actions" style="margin-top:18px">${btn('查看详情','trial-detail')}${btn('取消关注','favorite','text-button')}</div></div>`:`<div class="empty"><h3>还没有关注的研究线索</h3><p>可以先体验一个明确标记的示例条目。</p>${go('查看示例','clinical','试验检索','primary')}</div>`;
else body=`<div class="card"><h2>数据来源与时效</h2><div class="row"><div><b>临床试验数据</b><p>未接入。真实版本需保留登记URL、获取日期、更新责任与过期状态。</p></div>${pill('待开发')}</div><div class="row"><div><b>个人资料</b><p>当前仅在内存中保留模拟数据；刷新重置。</p></div>${pill('原型')}</div><p>工作台不会将“获取成功”标成“医学已核实”。</p></div>`;return head('临床',btn('预览交给 Agent 的内容','agent'))+subnav()+body;}
function nutrition(){const sub=state.sub.nutrition||subpages.nutrition[0];let body='';if(sub==='当下困扰')body=`<div class="grid two"><section class="card"><span class="eyebrow">从眼前的感受开始</span><h2 style="margin-top:10px">最近吃东西，有什么不一样？</h2><p>不必先计算摄入。可以记下食欲、吃不下的原因，或已有专业建议。</p><div class="actions" style="margin-top:22px">${go('记录进食变化','nutrition','进食与体重','primary')}${btn('整理我想问的问题','nutrition-question')}</div></section><section class="card"><h2>已有建议，值得留好</h2><p>正式版本会保留专业建议的日期和来源，用于回顾；不会把模拟内容作为营养处方。</p><div class="empty" style="margin-top:17px"><p>尚未保存专业建议。</p></div></section></div>`;
else if(sub==='进食与体重')body=`<div class="grid two"><section class="card"><h2>今天，记一点就好</h2><p>以下任选一项，模拟记录只在本页保留。</p><form id="nutrition-form"><div class="form-grid" style="margin-top:20px"><label><span class="form-label">进食情况（可不选）</span><select name="intake"><option value="">暂不记录</option><option>和平常差不多</option><option>比平常少一些</option><option>比平常少很多</option></select></label><label><span class="form-label">体重 kg（选填）</span><input name="weight" type="number" step="0.1" min="1" max="400" placeholder="不填也可以"></label><label class="wide"><span class="form-label">困难或想说的话（选填）</span><textarea name="note" maxlength="500" placeholder="例如：想把最近吃得少的情况告诉营养师"></textarea></label></div><div class="form-actions"><button class="primary" type="submit">保存模拟记录</button></div></form></section><section class="card"><h2>我的进食记录</h2>${state.nutrition.length?state.nutrition.map(n=>`<div class="saved-item"><b>${esc(n.intake||'进食情况未填')}</b><p>${n.weight?`体重 ${esc(n.weight)} kg · `:''}${esc(n.note||'无补充描述')}</p><small>本次原型记录 · ${esc(n.by)}</small></div>`).join(''):'<div class="empty" style="margin-top:20px"><h3>从第一条开始</h3><p>缺失不会记成零，也不会影响其他功能。</p></div>'}</section></div>`;
else body=`<div class="card"><h2>把变化带到下一次沟通里</h2><p>本次原型已保存${state.nutrition.length}条营养记录；专业建议和AI解释尚未接入。</p>${btn('保留一个营养问题','nutrition-question','primary')}${btn('查看我的问题','questions','text-button')}</div>`;return head('营养支持')+subnav()+body;}
function mind(){const sub=state.sub.mind||subpages.mind[0];let body='';if(sub==='当下感受')body=`<div class="notice pink">私密空间 · 这里的内容默认不进入一图秀、就诊摘要或问题导出。</div><div class="grid two"><section class="card"><span class="eyebrow">不必马上找到答案</span><h2 style="margin-top:9px">今天，你想给自己留些什么？</h2><form id="mind-form" style="margin-top:20px"><label><span class="form-label">这条记录属于谁？</span><select name="owner"><option>患者本人</option><option>照护者自己</option></select></label><label style="margin-top:16px"><span class="form-label">感受、睡眠，或者一个小小的困扰</span><textarea name="note" required maxlength="1000" placeholder="可以只写一句，也可以暂时不说。"></textarea></label><div class="form-actions"><button type="button" data-action="go" data-page="dashboard">现在先不写</button><button class="primary" type="submit">私密保存（模拟）</button></div></form></section><section class="card"><h2>可以慢慢来</h2><p>记录没有打卡要求，也不评价你是否“足够积极”。</p><p style="margin-top:16px">如果你想向家人或专业人员表达，之后可以自己选择适合分享的部分。</p><div class="private" style="margin-top:22px"><h3>照护者，也值得被照顾</h3><p>家属自己的感受单独保留，不写成患者的症状。</p></div>${go('看看支持资源 →','mind','支持资源','text-button')}</section></div>`;
else if(sub==='我的记录')body=`<section class="card"><div class="card-head"><h2>只留给记录主体的内容</h2>${pill('私密','pink')}</div>${state.moods.length?state.moods.map(m=>`<div class="saved-item private"><b>${esc(m.owner)}</b><p>${esc(m.note)}</p><small>模拟记录 · 未进入分享或导出</small></div>`).join(''):'<div class="empty"><h3>这里还没有记录</h3><p>不记录也可以使用其他帮助。</p></div>'}</section>`;
else body=`<div class="grid two"><section class="card"><h2>如何向别人表达我需要帮助？</h2><p>先从自己的话开始：眼前最困扰的是什么，希望别人帮哪一件事。</p>${btn('整理一个求助问题','support-question','primary')}</section><section class="card"><h2>支持资源的位置</h2><p>真实版本需要核实地区、服务范围、开放时间和更新日期。本原型未接入转介、真人咨询或危机服务。</p>${btn('查看资源设计说明','resource-info','text-button')}</section></div>`;return head('心理支持')+subnav()+body;}
function care(){const sub=state.sub.care||subpages.care[0];let body='';if(sub==='近期安排')body=`<div class="card"><div class="card-head"><div><h2>近期的安排</h2><p>本人待办与已有医嘱安排分开；当前日期全部为模拟。</p></div>${btn('＋ 新安排','add-task','primary')}</div>${tasksList()}${!state.tasks.length?'<div class="empty"><p>暂无安排，可以添加一项。</p></div>':''}<p class="small-note">完成待办不会生成给药记录；未接入系统后台通知。</p></div>`;
else if(sub==='不适记录')body=`<div class="card"><div class="card-head"><h2>把变化记下来，方便描述</h2>${btn('＋ 记录不适','symptom','primary')}</div>${state.symptoms.length?state.symptoms.map(s=>`<div class="saved-item"><b>${esc(s.note)}</b><p>本人自述 · 原型记录，不是诊断</p></div>`).join(''):'<div class="empty"><h3>这里还没有不适记录</h3><p>记录当时的感受、时间和想问的问题即可。</p></div>'}</div>`;
else if(sub==='康复与长期生活')body=`<div class="notice pink">这些是可选择的话题，不会要求每个人都经历或完成。</div><div class="grid three">${[['上肢与日常活动','保留已有康复建议，记录做日常事情时的困难。'],['身体形象与亲密关系','由你决定是否谈、和谁谈、分享多少。'],['长期生活与随访','把工作、睡眠、生活安排与想问的问题放在一起。']].map(([title,desc])=>`<section class="card"><h3>${title}</h3><p>${desc}</p>${btn('准备一个讨论问题 →','topic-question','text-button',`data-topic="${title}"`)}</section>`).join('')}</div><div class="help-box">原型不提供自动康复动作、强度或处置方案；正式内容需按个人情境和专业来源设计。</div>`;else body=summary();return head('全程管理')+subnav()+body;}
function questionsBody(){return `<div class="notice pink">模拟问题清单 · 可编辑、选择、删除。导出只包含勾选的问题，不含病历或私密记录。</div><div class="question-list">${state.questions.map(q=>`<div class="question-item"><input type="checkbox" data-q-select="${q.id}" aria-label="选入问题：${esc(q.text)}" ${q.selected?'checked':''}><div class="question-text"><textarea data-q-edit="${q.id}" aria-label="编辑就诊问题">${esc(q.text)}</textarea><small>${esc(q.source)}</small></div>${btn('×','delete-question','icon-button',`data-id="${q.id}" aria-label="删除此问题"`)}</div>`).join('')}</div>${!state.questions.length?'<div class="empty"><p>问题清单为空，可以从下面添加一个。</p></div>':''}<form id="question-form" style="margin-top:18px"><label><span class="form-label">再加一个想问的问题</span><textarea name="question" required maxlength="500" placeholder="用自己的话写下来"></textarea></label><div class="form-actions"><button type="submit">＋ 加入清单</button></div></form>`;}
function questionsModal(){openModal('下次就诊，想问的事',questionsBody(),`${btn('稍后继续','close')}${btn('下载所选问题 · Markdown','download','primary')}`);}
function review(){const sub=state.sub.review||subpages.review[0];let body='';if(sub==='问题清单')body=`<div class="card"><div class="card-head"><h2>就诊问题清单</h2>${btn('编辑与导出','questions','primary')}</div>${state.questions.map(q=>`<div class="row"><div><b>${esc(q.text)}</b><p>${esc(q.source)}</p></div>${pill(q.selected?'已选入':'未选入',q.selected?'green':'')}</div>`).join('')||'<p>暂无问题。</p>'}</div>`;
else if(sub==='已保留结果')body=`<div class="card"><h2>保留的准备结果</h2>${state.saved.length?state.saved.map(s=>`<div class="saved-item"><b>${esc(s.title)}</b><p>${esc(s.note)}</p></div>`).join(''):'<div class="empty" style="margin-top:20px"><h3>还没有保留的结果</h3><p>准备好问题后，下载动作会保留本次导出记录。</p></div>'}</div>`;else body=`<div class="grid two"><section class="card"><h2>报告</h2><p>真实多格式病情报告未接入。当前可下载模拟问题清单的Markdown文件。</p>${btn('预览问题并下载','questions','primary')}</section><section class="card"><h2>原生 Agent 任务</h2><p>此原型未连接DSH或模型，不会创建会话、发送消息或读取目录。</p>${btn('预览未来发送内容','agent','soft')}</section></div>`;return head('收藏与回顾')+subnav()+body;}
function render(){const functions={dashboard,records,timeline:timelinePage,clinical,nutrition,mind,care,review};$('#nav').innerHTML=pages.map(([id,label,i])=>`<button class="nav-button" data-action="go" data-page="${id}" ${state.page===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${state.page===id?'<span class="nav-dot"></span>':''}</button>`).join('');$('#breadcrumb').textContent=pages.find(p=>p[0]===state.page)[1];$('#main').innerHTML=functions[state.page]();}
function addQuestion(text,source='本人添加 · 模拟问题'){state.questions.push({id:'q'+crypto.randomUUID(),text,source,selected:true});toast('已加入问题清单，可在收藏与回顾中编辑');render();}
function source(name){openModal('材料原文 · 模拟示例',`<div class="notice">这不是实际报告。以下内容为交互测试编写，不代表个人病情。</div><article class="document"><h3>${esc(name||'治疗记录 · 示例')}</h3><p>【模拟材料 / 第 1 页】</p><p>本页用于演示来源回溯。报告名称、发生日期、标本信息或治疗记录应与对应字段关联，而不是分散存入每个页面。</p><p>示例摘录：实际治疗日期 2026-10-12；记录名称为“第2次治疗（示例）”；下一次就诊日期不清晰。</p><p>所有内容均为虚构，无真实机构、身份或患者记录。</p></article>`,btn('返回工作台','close','primary'));}
function addTask(){openModal('添加一项安排',`<form id="task-form"><label><span class="form-label">安排内容</span><input name="title" required maxlength="120" placeholder="例如：整理下次就诊的问题"></label><label style="margin-top:16px"><span class="form-label">日期</span><input type="date" name="date" required value="2026-10-20"></label><label style="margin-top:16px"><span class="form-label">补充说明（选填）</span><textarea name="note" maxlength="500" placeholder="这项安排来自哪里？还有什么需要确认？"></textarea></label></form>`,`${btn('取消','close')}<button type="submit" form="task-form" class="primary">保存模拟安排</button>`);}
function agent(){openModal('交给原生 Agent 之前',`<div class="notice">原型未接入DSH、AI或任何外部服务。下面只预览内容，不会发送。</div><h3>拟定任务</h3><p>请根据本次选择的资料，帮助整理需要进一步核实的问题。</p><details open><summary>本次内容范围</summary><ul><li>当前业务页面：${esc(pages.find(p=>p[0]===state.page)[1])}</li><li>模拟材料目录，共${state.docs.length}份；不读取实际文件</li><li>患者/照护者的私密心理记录不加入</li><li>未核对内容保留草稿状态与来源</li></ul></details><p class="small-note">真实会话、模型、权限、草稿与显式发送由DSH原生能力管理。AI帮助范围仍待产品讨论。</p>`,`${btn('返回','close')}<button disabled>未接入，无法发送</button>`);}
const actions={go:(el)=>navigate(el.dataset.page,el.dataset.sub),sub:(el)=>{state.sub[state.page]=el.dataset.sub;render();},close:closeModal,questions:questionsModal,source:(el)=>source(el.dataset.source),agent,
  'task-toggle':(el)=>{const task=state.tasks.find(t=>t.id===el.dataset.id);task.done=!task.done;render();toast(task.done?'安排已完成；不会生成治疗记录':'已重新打开安排');},
  'task-detail':(el)=>{const task=state.tasks.find(t=>t.id===el.dataset.id);openModal('安排详情',`<h3>${esc(task.title)}</h3><p>${task.date.includes('-')?task.date:'2026.'+task.date} · ${esc(task.note)}</p><p class="small-note">这是本人待办，完成不会成为实际治疗事件。</p>`,`${btn('返回','close')}${btn('取消这项安排','delete-task','',`data-id="${task.id}"`)}`);},
  'delete-task':(el)=>{state.tasks=state.tasks.filter(t=>t.id!==el.dataset.id);closeModal();render();toast('已取消模拟安排');},'add-task':addTask,
  record:()=>openModal('今天，想先记下什么？',`<div class="grid three">${go('进食与体重','nutrition','进食与体重','soft')}${go('身体不适','care','不适记录','soft')}${go('感受与睡眠','mind','当下感受','soft')}</div><p class="small-note">任选一项即可；进入其他页面会关闭此窗口。</p>`,btn('以后再说','close')),
  welcome:()=>openModal('我们可以先理清一件小事',`<p>一下子面对这么多信息，可能很难消化。现在不需要填好一份完整档案。</p><div class="grid" style="margin-top:22px">${go('先看看，手里的材料怎么整理','records','资料库','soft')}${go('我想先说说自己的感受','mind','当下感受','soft')}${btn('先留下一个想问的问题','questions','soft')}</div>`,btn('现在先看看','close')),
  'load-report':()=>{if(state.parsing)return;if(state.loaded){toast('模拟报告已载入，没有重复新增');return;}state.parsing=true;state.parseError=false;render();setTimeout(()=>{state.docs.push({id:'d4',name:'复查记录 · 新模拟报告',date:'2026-10-16',type:'其他',status:'待核对'});state.loaded=true;state.parsing=false;render();toast('模拟材料整理完成，可查看草稿');},900);},
  'parse-fail':()=>{state.parseError=true;render();},retry:()=>{state.parseError=false;toast('模拟重试完成；原件始终保留');render();},
  candidate:(el)=>{const c=state.candidates.find(c=>c.id===el.dataset.id);openModal('核对这一项内容',`<div class="notice">核对表示转录已检查，不等于医学专业审核。</div><form id="candidate-form" data-id="${c.id}"><label><span class="form-label">${esc(c.name)}</span><input name="value" value="${esc(c.value)}" required maxlength="160"></label><p class="small-note">来源：${esc(c.source)}。如暂时不清楚，可保留待核对状态。</p></form>${btn('查看原文 ↗','source','text-button','data-source="治疗记录 · 示例"')}`,`${btn('现在先不核对','close')}<button form="candidate-form" type="submit" class="primary">接受这项模拟记录</button>`);},
  'add-review-question':()=>addQuestion('请帮我核实这份治疗记录中的实际日期和下次就诊安排。','整理草稿衍生 · 核实问题，无预设病情'),
  metric:(el)=>{state.metricOpen[el.dataset.id]=!state.metricOpen[el.dataset.id];render();},
  point:(el)=>openModal('一个数据点，也能找到出处',`<h3>白细胞 ${esc(el.dataset.value)} × 10⁹/L</h3><p>采样日期：2026.${esc(el.dataset.date)} · 模拟数值</p><p class="small-note">来源：血常规报告示例。不同单位/检测方法的记录需要先核对可比性。</p>`,`${btn('返回','close')}${btn('查看原文','source','primary','data-source="血常规报告 · 示例"')}`),
  favorite:()=>{state.favorite=!state.favorite;render();toast(state.favorite?'已关注虚构示例，可在“我的关注”回顾':'已取消关注示例');},
  'trial-detail':()=>openModal('研究条目详情 · 虚构示例',`<div class="notice">条目A仅用于交互设计，不是真实研究，不含可用登记号或研究中心。</div><dl class="two-col-info"><dt>研究状态</dt><dd>未接入真实信息</dd><dt>登记来源</dt><dd>未来需保留原始URL与更新日期</dd><dt>参与条件</dt><dd>由登记原文及研究中心核实</dd><dt>你的材料</dt><dd>可整理病理、实际治疗及待核实项</dd></dl>`,`${btn('返回','close')}${go('查看资料对照','clinical','资料对照','primary')}`),
  'add-trial-question':()=>addQuestion('向研究中心询问：还需要提供哪些资料来核实参与条件？','虚构条目A · 待核实问题'),
  'nutrition-question':()=>addQuestion('最近进食变化，我需要向医生或营养师说明哪些情况？','本人选择 · 营养沟通'),
  'support-question':()=>addQuestion('我希望和专业人员谈谈最近的感受，可以怎样获得合适的支持？','本人主动保留 · 不含私密记录'),
  'topic-question':(el)=>addQuestion(`关于${el.dataset.topic}，我希望询问有哪些适合进一步讨论的支持方式。`,'本人选择 · 长期生活'),
  'resource-info':()=>openModal('支持资源如何进入工作台',`<p>真实版本将按地区、服务范围、联系方式、获取日期及核实状态维护资源。</p><p style="margin-top:15px">目前没有接入真人服务、在线监护或危机评估；此处演示资源说明与返回路径。</p>`,btn('返回','close','primary')),
  symptom:()=>openModal('记录一点身体变化',`<form id="symptom-form"><label><span class="form-label">发生了什么？</span><textarea name="note" required maxlength="500" placeholder="例如：从什么时候开始，感觉怎样，想问什么"></textarea></label><p class="small-note">这是本人自述；原型不评估症状或给出处理方案。</p></form>`,`${btn('取消','close')}<button type="submit" form="symptom-form" class="primary">保存模拟记录</button>`),
  'delete-question':(el)=>{state.questions=state.questions.filter(q=>q.id!==el.dataset.id);questionsModal();render();toast('已删除这个模拟问题');},
  download:()=>{const questions=state.questions.filter(q=>q.selected);if(!questions.length){toast('请先选择至少一个问题');return;}if(questions.some(q=>!q.text.trim())){toast('请补充所选空白问题，或取消选入');return;}const text='# 小粉宝 · 模拟就诊问题清单\n\n交互原型 v0.1 · 全部为模拟资料，不包含真实病历或私密心理记录。\n\n'+questions.map((q,i)=>`${i+1}. ${q.text}\n   来源：${q.source}`).join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='小粉宝-模拟就诊问题清单.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);state.saved.push({title:'模拟问题清单已导出',note:`本次选入${questions.length}个问题；历史导出不随之后的编辑改写。`});toast('已生成模拟问题清单文件');render();},
  help:()=>openModal('这版可以怎样体验',`<ol><li>从看板进入资料库，载入模拟报告或演示解析失败。</li><li>看整理草稿，单独核对/更正，或者暂时跳过。</li><li>进入一图秀，切换时间范围、点数据、独立展开卡片。</li><li>记录一项进食、不适或私密感受。</li><li>编辑问题清单，下载所选问题的Markdown文件。</li></ol><p>所有数据在内存中，刷新重置；不读取实际文件，不调用AI或DSH。正式业务开发等待用户确认原型。</p>`,btn('开始体验','close','primary'))};
document.addEventListener('click',(event)=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(action==='go'&&$('#dialog').open)closeModal();if(actions[action])actions[action](el);});
document.addEventListener('keydown',(event)=>{const el=event.target.closest('circle[data-action]');if(el&&(event.key==='Enter'||event.key===' ')){event.preventDefault();actions[el.dataset.action](el);}});
document.addEventListener('change',(event)=>{const el=event.target;if(el.id==='stage-select'){state.stage=el.value;toast('已切换关注阶段；不会改写病情或隐藏模块');}if(el.id==='range-select'){state.range=el.value;render();}if(el.dataset.qSelect){const q=state.questions.find(q=>q.id===el.dataset.qSelect);if(q)q.selected=el.checked;}});
document.addEventListener('input',(event)=>{const el=event.target;if(el.id==='search'){state.query=el.value;$('#docs-table').innerHTML=docsTable();}if(el.dataset.qEdit){const q=state.questions.find(q=>q.id===el.dataset.qEdit);if(q)q.text=el.value;}});
document.addEventListener('submit',(event)=>{const form=event.target;event.preventDefault();const data=new FormData(form);if(form.id==='task-form'){const date=String(data.get('date'));state.tasks.push({id:'t'+crypto.randomUUID(),date:date,title:String(data.get('title')).trim(),note:String(data.get('note')||'本人安排 · 原型记录'),done:false});closeModal();render();toast('模拟安排已保存');}
else if(form.id==='candidate-form'){const c=state.candidates.find(c=>c.id===form.dataset.id);c.value=String(data.get('value')).trim();c.status='accepted';const dateRecord=state.candidates.find(c=>c.id==='c1');const titleRecord=state.candidates.find(c=>c.id==='c2');if(dateRecord.status==='accepted'&&titleRecord.status==='accepted'&&/^2026-\d{2}-\d{2}$/.test(dateRecord.value)){const item={id:'e4',date:dateRecord.value.slice(5).replace('-','.'),title:titleRecord.value,type:'已接受模拟转录',source:'治疗记录 · 示例'};state.events=state.events.filter(e=>e.id!=='e4');state.events.push(item);}else{state.events=state.events.filter(e=>e.id!=='e4');}closeModal();render();toast('已接受这一项；其他字段状态保持原样');}
else if(form.id==='nutrition-form'){const item={intake:String(data.get('intake')||''),weight:String(data.get('weight')||''),note:String(data.get('note')||'').trim(),by:'本人'};if(!item.intake&&!item.weight&&!item.note){toast('任选一项记录，或直接返回');return;}state.nutrition.unshift(item);render();toast('已保存一条模拟营养记录');}
else if(form.id==='mind-form'){state.moods.unshift({owner:String(data.get('owner')),note:String(data.get('note')).trim()});state.sub.mind='我的记录';render();toast('已私密保存模拟记录，不加入分享');}
else if(form.id==='symptom-form'){state.symptoms.unshift({note:String(data.get('note')).trim()});closeModal();render();toast('已保存模拟自述');}
else if(form.id==='question-form'){const text=String(data.get('question')).trim();if(!text){toast('请写下一个问题');return;}addQuestion(text);questionsModal();}});
$('#font-toggle').addEventListener('click',()=>{const large=document.body.classList.toggle('large');$('#font-toggle').setAttribute('aria-pressed',String(large));$('#font-toggle').textContent=large?'标准字 Aa':'大字 Aa';});
render();
